import assert from 'node:assert/strict';
import {prepareFixture} from './prepare-fixture.mjs';
import {LoadingCoordinator} from '../../../client/assets/scripts/net/LoadingCoordinator.ts';
import {RecoveryCoordinator} from '../../../client/assets/scripts/net/RecoveryCoordinator.ts';
export async function runRecoveryDemo(log=()=>{}){
 const h=await prepareFixture(),saved=new Map(),persistence={load:k=>saved.get(k)??null,save:(k,v)=>v===null?saved.delete(k):saved.set(k,v)},lost=new Set();
 const transport={send:async text=>{const q=JSON.parse(text),r=await(q.query?h.service.query(q):h.service.execute(q));if(lost.delete(q.command))throw Error('simulated lost reply');return JSON.stringify(r);},queryOriginalControl:async text=>JSON.stringify(await h.service.queryOriginalControl(JSON.parse(text)))};
 const loading=new LoadingCoordinator(transport,persistence,{load:(ref,release)=>h.service.resolveResource(release,ref)});await loading.prepare(h.command);assert.equal(loading.state.status,'loaded');
 const manifest=loading.state.manifest,state=await h.query();await h.service.execute({...h.auth,command:'challenge.activateRoom',operationId:'demo-recovery-activate',expected:state.versions,payload:{characterId:h.characterId,rolePlayEpoch:h.character().rolePlayEpoch,challengeId:h.challengeId,roomAttemptId:manifest.roomAttemptId,manifestHash:manifest.manifestHash,expectedRevision:1}});
 const identity={...h.auth,characterId:h.characterId,rolePlayEpoch:h.character().rolePlayEpoch,challengeId:h.challengeId},payload={characterId:identity.characterId,rolePlayEpoch:identity.rolePlayEpoch,challengeId:identity.challengeId};
 let client=new RecoveryCoordinator(transport,persistence);client.init(identity);h.clock.now=()=>4000;await client.control({...h.auth,command:'scene.suspend',controlSeq:1,leaseRevision:0,payload:{...payload,sceneEpoch:1,timelineEpoch:1}});assert.equal(client.state.status,'recovering');log('suspend: paid attempt frozen; prediction disabled');
 h.clock.now=()=>8000;lost.add('scene.resumePrepare');await client.control({...h.auth,command:'scene.resumePrepare',controlSeq:2,leaseRevision:1,payload:{...payload,sceneEpoch:1,timelineEpoch:1,checkpointRevision:client.state.data.state.checkpointRevision}});assert.equal(client.state.status,'unknown');
 client=new RecoveryCoordinator(transport,persistence);client.init(identity);await client.retry();assert.equal(client.state.status,'recovering');client.useLoadedResources(loading);await client.fetchPages('recovery-page');log('reopen: original resume recovered; complete public proof verified');
 const ready=seq=>({...h.auth,command:'scene.ready',controlSeq:seq,leaseRevision:seq-1,payload:{...payload,...Object.fromEntries(Object.entries(client.state.data.readyTicket).filter(([k])=>k!=='deadline'))}});
 lost.add('scene.ready');await client.control(ready(3));assert.equal(client.state.status,'unknown');client=new RecoveryCoordinator(transport,persistence);client.init(identity);client.useLoadedResources(loading);await client.fetchPages('reloaded-recovery');await client.retry();assert.equal(client.state.data.state.roomPhase,'awaitingReady');assert.equal(client.state.predictionEnabled,false);assert.equal(client.state.data.state.anchorWallAt,null);log('recovery-ready: same attempt loading resumed; enemies have no anchor');
 await client.fetchPages('final-baseline');h.clock.now=()=>10000;lost.add('scene.ready');await client.control(ready(4));assert.equal(client.state.status,'unknown');client=new RecoveryCoordinator(transport,persistence);client.init(identity);assert.equal(client.state.predictionEnabled,false);client.useLoadedResources(loading);await client.fetchPages('reloaded-final');await client.retry();assert.equal(client.state.status,'active');assert.equal(client.state.predictionEnabled,true);assert.equal(client.state.data.state.acceptedTick,500);assert.equal(h.store.inspect(h.challengeId).staminaSnapshot.remaining,307);assert.equal(h.store.inspect(h.challengeId).purpleEncounter.spawnId,'purple-extra');
 log('final-ready: exact original plus fresh status; 5 eligible seconds; one room fee; prediction enabled');return {h,client,loading,transport,persistence,identity};
}
